/** 一请求一响应（unary）：请求与回复经 idempotencyKey 关联 seq。 */
async onEvent(call: any, cb: any): Promise<void> {
  const env = call.request;
  let payload: unknown = null;
  if (env?.payload?.length) {
    try {
      payload = JSON.parse(Buffer.from(env.payload).toString("utf8"));
    } catch {
      payload = null;
    }
  }
  let value: unknown;
  try {
    // 契约显式化（P6）：deadlineMs（相对毫秒，未设=0→null）与 priority 原样透传——
    // 契约字段在绑定层不得静默丢弃。proto-loader keepCase:false → camelCase。
    value = await plugin.onEvent({
      target: env?.ty ?? "",
      payload,
      deadlineMs: typeof env?.deadlineMs === "number" && env.deadlineMs > 0 ? env.deadlineMs : null,
      priority: env?.priority ?? 1,
    });
